escala_tipografica.css:
.sl-post-content h1{font-size:clamp(1.8rem,4vw,2.5rem);margin-bottom:1.5rem}
.sl-post-content h2{font-size:clamp(1.4rem,3vw,1.875rem);margin:2rem 0 1rem}
.sl-post-content h3{font-size:clamp(1.2rem,2.5vw,1.5rem);margin:1.75rem 0 .75rem}
.sl-post-content p{font-size:1.0625rem;line-height:1.85;margin-bottom:1.25rem}
.sl-post-content blockquote{border-left:4px solid var(--sl-primary);padding:.75rem 1.25rem;background:rgba(var(--sl-primary-rgb,0,123,255),.06);border-radius:0 8px 8px 0;font-style:italic}
.sl-post-content img{max-width:100%;height:auto;border-radius:8px;margin:1.5rem 0}
.sl-post-content pre,.sl-post-content code{font-family:'Roboto Mono',monospace;font-size:.875rem}
